INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DML nur zum Erstellen von Tabellen gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "DML manipuliert Daten"}, {"text": "Ja", "correct": false, "because": "Das ist DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe übernimmt DML in einer Datenbank?', 3, '[{"text": "Daten manipulieren", "correct": true, "because": "Einfügen, Ändern, Löschen"}, {"text": "Tabellen definieren", "correct": false, "because": "Das ist DDL"}, {"text": "Daten abfragen", "correct": false, "because": "Das ist DQL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle gehören zu DML?', 5, '[{"text": "INSERT", "correct": true, "because": "Daten einfügen"}, {"text": "UPDATE", "correct": true, "because": "Daten ändern"}, {"text": "CREATE", "correct": false, "because": "Das ist DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DML ändert Daten. b) Es erstellt Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenbanken sind DDL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von DML?', 4, '[{"text": "Datenintegrität", "correct": false, "because": "Wichtig für Konsistenz"}, {"text": "Syntax", "correct": false, "because": "Notwendig"}, {"text": "Tabellenfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DML Daten abfragt?', 2, '[{"text": "Nein", "correct": true, "because": "Abfragen sind DQL"}, {"text": "Ja", "correct": false, "because": "DML manipuliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt Daten in eine Tabelle ein?', 3, '[{"text": "INSERT", "correct": true, "because": "Daten hinzufügen"}, {"text": "SELECT", "correct": false, "because": "Abfragen"}, {"text": "ALTER", "correct": false, "because": "Struktur ändern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen erlaubt DML?', 5, '[{"text": "Einfügen", "correct": true, "because": "INSERT"}, {"text": "Löschen", "correct": true, "because": "DELETE"}, {"text": "Tabellen erstellen", "correct": false, "because": "DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DML ist für Datenänderung. b) Es definiert Tabellenstrukturen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Strukturen sind DDL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DML?', 4, '[{"text": "Tabellen", "correct": false, "because": "Datenbasis"}, {"text": "Datenbankzugriff", "correct": false, "because": "Notwendig"}, {"text": "Hardware-Design", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist SELECT ein DML-Befehl?', 2, '[{"text": "Nein", "correct": true, "because": "SELECT ist DQL"}, {"text": "Ja", "correct": false, "because": "DML manipuliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle ändern bestehende Daten?', 4, '[{"text": "UPDATE", "correct": true, "because": "Ändert Werte"}, {"text": "DELETE", "correct": true, "because": "Entfernt Daten"}, {"text": "DROP", "correct": false, "because": "DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DML Datenbanken erstellt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Das ist DDL"}, {"text": "Ja", "correct": false, "because": "DML manipuliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DML?', 3, '[{"text": "Datenkonsistenz", "correct": true, "because": "Integrität sichern"}, {"text": "Tabellenlayout", "correct": false, "because": "DDL"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DELETE entfernt Daten. b) Es fragt Daten ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abfragen sind DQL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DML?', 5, '[{"text": "Datenpflege", "correct": true, "because": "Änderungen möglich"}, {"text": "Flexibilität", "correct": true, "because": "Vielfältige Operationen"}, {"text": "Tabellenstruktur", "correct": false, "because": "DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DML unwichtig?', 3, '[{"text": "Syntax", "correct": false, "because": "Notwendig"}, {"text": "Datenbankzugriff", "correct": false, "because": "Grundlage"}, {"text": "Monitorgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DML Tabellen löschen?', 3, '[{"text": "Nein", "correct": true, "because": "Das ist DDL (DROP)"}, {"text": "Ja", "correct": false, "because": "DML nur Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DML Transaktionen unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "COMMIT/ROLLBACK"}, {"text": "Nein", "correct": false, "because": "Transaktionen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl gehört nicht zu DML?', 4, '[{"text": "CREATE", "correct": true, "because": "DDL-Befehl"}, {"text": "INSERT", "correct": false, "because": "DML"}, {"text": "UPDATE", "correct": false, "because": "DML"}]');
